	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		LoanAccount
	 */
		public LoanAccount createLoanAccount( CreateLoanAccountCommand command ) {

		LoanAccount entity = new LoanAccount();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setLoanAccountId( command.getLoanAccountId() );
            entity.setLoanNumber( command.getLoanNumber() );
            entity.setPrincipalAmount( command.getPrincipalAmount() );
            entity.setOutstandingPrincipal( command.getOutstandingPrincipal() );
            entity.setInterestRate( command.getInterestRate() );
            entity.setOriginationDate( command.getOriginationDate() );
            entity.setMaturityDate( command.getMaturityDate() );
            entity.setPaymentDayOfMonth( command.getPaymentDayOfMonth() );
            entity.setCurrency( command.getCurrency() );
            entity.setLoanType( command.getLoanType() );
            entity.setRateType( command.getRateType() );
            entity.setCompounding( command.getCompounding() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of LoanAccount {0} ", entity.toString() );

		return entity;
	}

