	/**
	 * Method to retrieve the LoanAccount via LoanAccountFetchOneSummary
	 * @param 	summary LoanAccountFetchOneSummary
	 * @return 	LoanAccountFetchOneResponse
	 */
	public LoanAccount getLoanAccount( LoanAccountFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "LoanAccountFetchOneSummary arg cannot be null" );

		LoanAccount entity = null;
		UUID id = summary.getLoanAccountId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a LoanAccount using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


